#include <vector>
#include <iostream>

void check(const std::vector<int>& v) {
    // Recommended practice
    if (v.empty()) {
        std::cout << "Container is empty (Efficient check)\n";
    }

    // Functional, but discouraged style
    if (v.size() == 0) {
        std::cout << "Container is empty (Less idiomatic check)\n";
    }
}

int main() {
    std::vector<int> v;
    check(v);
    return 0;
}
